insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-so-201","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Water (18 g mol⁻¹), 180 g, holds 6.0 g of a non-volatile solute. If relative lowering is 0.010, the molar mass of the solute is nearest","options":["60 g mol⁻¹","180 g mol⁻¹","6.0 g mol⁻¹","18 g mol⁻¹"],"answer_index":0,"explanation":"n(water) = 10 mol; $x_B \\approx n_B / n_A = 0.010$ gives $n_B = 0.10$ mol, so $M = 6.0 / 0.10 = 60$ g mol⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-202","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Pure solvent vapour pressure 50 kPa falls to 49 kPa on adding a non-volatile solute. The mole fraction of solvent is","options":["0.98","0.02","0.50","1.02"],"answer_index":0,"explanation":"$x_{\\mathrm{solvent}} = p / p^\\circ = 49/50 = 0.98$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-203","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Urea and glucose solutions that are equimolal in the same solvent exhibit","options":["equal relative lowering, both being non-electrolytes","urea twice the lowering of glucose","zero lowering","lowering equal to i = 2"],"answer_index":0,"explanation":"Equal molality in a dilute aqueous pair means essentially equal $x_B$ and therefore equal $(p^\\circ - p)/p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-204","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A flask contains 3.0 g of a non-volatile solute ($M = 60$) together with 117 g of a solvent ($M = 78$). Relative lowering of vapour pressure is nearest","options":["0.032","0.050","0.20","0.967"],"answer_index":0,"explanation":"$n_B = 0.050$, $n_A = 1.50$, so $x_B = 0.050 / 1.55 \\approx 0.032 = (p^\\circ - p)/p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-205","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute causes the boiling point of a liquid to","options":["rise","fall","stay fixed","equal the freezing point"],"answer_index":0,"explanation":"The solution must be hotter before its vapour pressure reaches the external pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-206","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The molal boiling-point elevation constant $K_b$ is also called the","options":["ebullioscopic constant","cryoscopic constant","Henry constant","Rydberg constant"],"answer_index":0,"explanation":"$K_b$ is the ebullioscopic (boiling-point) constant of the solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-207","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$\\Delta T_b$ for a dilute non-electrolyte solution is proportional to","options":["the molality of the solute","the molarity only","the mole fraction of solvent only","the charge of the solute"],"answer_index":0,"explanation":"The working relation is $\\Delta T_b = K_b m$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-208","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"$K_b$ is a characteristic of","options":["the solvent","the chemical identity of the solute","the volume of the flask","the colour of the solution"],"answer_index":0,"explanation":"Each solvent has its own molal elevation constant, independent of the non-electrolyte used.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-209","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Boiling point rises because the solution must be heated until its","options":["vapour pressure again equals the external pressure","freezing point equals 0 °C","osmotic pressure vanishes","$K_H$ is zero"],"answer_index":0,"explanation":"A non-volatile solute lowers p, so a higher T is needed to restore p = 1 atm.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-210","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A convenient unit of $K_b$ is","options":["K kg mol⁻¹","K L mol⁻¹","atm kg mol⁻¹","J mol⁻¹"],"answer_index":0,"explanation":"$\\Delta T_b = K_b m$ with m in mol kg⁻¹, so $K_b$ has unit K kg mol⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"boiling-elevation","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
